// Parse solution architecture request
const request = $input.first().json;

// Required fields validation
if (!request.automation_request) {
  return [{
    json: {
      error: 'Missing required field: automation_request',
      status: 'invalid_request'
    }
  }];
}

// Build comprehensive architecture context
const context = {
  request_id: generateRequestId(),
  timestamp: new Date().toISOString(),
  automation_request: request.automation_request,
  character_context: {
    character_id: request.character_context?.character_id || 'unknown',
    character_class: request.character_context?.character_class || 'unknown',
    character_level: request.character_context?.character_level || 1,
    party_role: request.character_context?.party_role || 'member',
    play_style: request.character_context?.play_style || 'balanced'
  },
  business_logic: request.business_logic_result || {},
  technical_requirements: request.technical_requirements || {},
  architecture_options: {
    complexity_level: request.complexity_level || 'medium',
    integration_scope: request.integration_scope || 'standard',
    performance_requirements: request.performance_requirements || 'standard',
    error_handling_level: request.error_handling_level || 'comprehensive',
    testing_level: request.testing_level || 'standard',
    documentation_level: request.documentation_level || 'comprehensive'
  },
  delivery_preferences: {
    include_explanations: request.include_explanations !== false,
    include_setup_instructions: request.include_setup_instructions !== false,
    include_usage_examples: request.include_usage_examples !== false,
    include_troubleshooting: request.include_troubleshooting !== false,
    format_preference: request.format_preference || 'character_friendly'
  }
};

function generateRequestId() {
  return 'sar_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
}

return [{
  json: context
}];

// Create architecture blueprint and component mapping
const context = $input.first().json;

// Architecture component templates
const architectureTemplates = {
  protection_system: {
    components: [
      {
        name: 'Threat Monitoring Service',
        purpose: 'Continuously monitor for threats to party members',
        type: 'monitoring',
        dependencies: ['party_state_tracker', 'threat_detector'],
        complexity: 'medium'
      },
      {
        name: 'Protection Decision Engine',
        purpose: 'Determine optimal protection strategies',
        type: 'decision_engine',
        dependencies: ['threat_monitoring', 'character_capabilities'],
        complexity: 'high'
      },
      {
        name: 'Protection Execution Service',
        purpose: 'Execute protection abilities and spells',
        type: 'execution',
        dependencies: ['protection_decision_engine', 'action_coordinator'],
        complexity: 'medium'
      },
      {
        name: 'Resource Management Module',
        purpose: 'Manage spell slots, action economy, and resources',
        type: 'resource_management',
        dependencies: ['protection_execution', 'character_state'],
        complexity: 'low'
      }
    ],
    data_flow: 'threat_monitoring → protection_decision → protection_execution → resource_management',
    integration_points: ['combat_engine', 'health_tracker', 'party_communicator']
  },
  combat_system: {
    components: [
      {
        name: 'Combat Analysis Service',
        purpose: 'Analyze combat situation and identify opportunities',
        type: 'analysis',
        dependencies: ['combat_state_tracker', 'enemy_analyzer'],
        complexity: 'medium'
      },
      {
        name: 'Target Prioritization Engine',
        purpose: 'Determine optimal targets for attacks',
        type: 'decision_engine',
        dependencies: ['combat_analysis', 'threat_assessment'],
        complexity: 'high'
      },
      {
        name: 'Attack Coordination Service',
        purpose: 'Execute attacks and coordinate with party',
        type: 'execution',
        dependencies: ['target_prioritization', 'ability_manager'],
        complexity: 'medium'
      },
      {
        name: 'Combat Resource Optimizer',
        purpose: 'Optimize use of abilities and resources',
        type: 'optimization',
        dependencies: ['attack_coordination', 'resource_tracker'],
        complexity: 'high'
      }
    ],
    data_flow: 'combat_analysis → target_prioritization → attack_coordination → resource_optimization',
    integration_points: ['threat_monitoring', 'buff_manager', 'position_tracker']
  },
  healing_system: {
    components: [
      {
        name: 'Health Monitoring Service',
        purpose: 'Monitor party health and detect injuries',
        type: 'monitoring',
        dependencies: ['health_tracker', 'condition_detector'],
        complexity: 'low'
      },
      {
        name: 'Triage Decision Engine',
        purpose: 'Prioritize healing based on urgency and importance',
        type: 'decision_engine',
        dependencies: ['health_monitoring', 'role_analyzer'],
        complexity: 'high'
      },
      {
        name: 'Healing Execution Service',
        purpose: 'Cast healing spells and provide medical aid',
        type: 'execution',
        dependencies: ['triage_decision', 'spell_manager'],
        complexity: 'medium'
      },
      {
        name: 'Prevention Planning Service',
        purpose: 'Anticipate damage and provide preventive healing',
        type: 'prediction',
        dependencies: ['threat_analyzer', 'damage_predictor'],
        complexity: 'high'
      }
    ],
    data_flow: 'health_monitoring → triage_decision → healing_execution → prevention_planning',
    integration_points: ['protection_system', 'condition_remover', 'buff_manager']
  },
  utility_system: {
    components: [
      {
        name: 'Situation Analyzer',
        purpose: 'Analyze current situation for utility opportunities',
        type: 'analysis',
        dependencies: ['environment_tracker', 'opportunity_detector'],
        complexity: 'medium'
      },
      {
        name: 'Utility Selection Engine',
        purpose: 'Select optimal utility actions for situations',
        type: 'decision_engine',
        dependencies: ['situation_analyzer', 'tool_inventory'],
        complexity: 'medium'
      },
      {
        name: 'Utility Execution Service',
        purpose: 'Execute utility skills and abilities',
        type: 'execution',
        dependencies: ['utility_selection', 'skill_manager'],
        complexity: 'low'
      },
      {
        name: 'Problem Solving Coordinator',
        purpose: 'Coordinate multi-step problem resolution',
        type: 'coordination',
        dependencies: ['utility_execution', 'planning_engine'],
        complexity: 'high'
      }
    ],
    data_flow: 'situation_analyzer → utility_selection → utility_execution → problem_solving',
    integration_points: ['exploration_system', 'puzzle_solver', 'crafting_system']
  }
};

// Determine automation type and select appropriate template
const automationType = determineAutomationType(context.automation_request);
const selectedTemplate = architectureTemplates[automationType] || architectureTemplates.utility_system;

function determineAutomationType(request) {
  const description = (request.description || request.goal || '').toLowerCase();

  if (description.includes('protect') || description.includes('defend') || description.includes('shield')) {
    return 'protection_system';
  }
  if (description.includes('attack') || description.includes('damage') || description.includes('combat')) {
    return 'combat_system';
  }
  if (description.includes('heal') || description.includes('restore') || description.includes('aid')) {
    return 'healing_system';
  }

  return 'utility_system';
}

// Create architecture blueprint
const architectureBlueprint = {
  automation_type: automationType,
  architecture_pattern: 'microservices_with_shared_data',
  components: selectedTemplate.components.map(component => ({
    ...component,
    implementation_priority: calculateImplementationPriority(component),
    estimated_development_time: estimateDevelopmentTime(component, context.architecture_options.complexity_level),
    testing_requirements: determineTestingRequirements(component, context.architecture_options.testing_level)
  })),
  data_flow: selectedTemplate.data_flow,
  integration_points: selectedTemplate.integration_points,
  architecture_decisions: {
    communication_pattern: 'event_driven',
    data_storage: 'distributed_with_caching',
    error_handling: context.architecture_options.error_handling_level,
    scaling_approach: 'horizontal_with_load_balancing',
    monitoring_approach: 'comprehensive_with_alerting'
  },
  technology_stack: {
    primary_language: 'python',
    framework: 'n8n_workflow',
    ai_integration: 'deepseek_api',
    data_storage: 'sqlite_with_redis_cache',
    communication: 'webhook_and_event_bus'
  }
};

function calculateImplementationPriority(component) {
  if (component.type === 'monitoring' || component.type === 'decision_engine') return 'high';
  if (component.type === 'execution') return 'high';
  if (component.type === 'resource_management') return 'medium';
  return 'low';
}

function estimateDevelopmentTime(component, complexityLevel) {
  const baseTime = {
    monitoring: 2,
    analysis: 3,
    decision_engine: 5,
    execution: 4,
    resource_management: 2,
    optimization: 4,
    prediction: 6,
    coordination: 5
  };

  const complexityMultipliers = {
    simple: 0.8,
    medium: 1.0,
    complex: 1.5,
    enterprise: 2.0
  };

  return Math.ceil(baseTime[component.type] * complexityMultipliers[complexityLevel]);
}

function determineTestingRequirements(component, testingLevel) {
  const requirements = ['unit_tests'];

  if (testingLevel === 'comprehensive' || testingLevel === 'advanced') {
    requirements.push('integration_tests', 'performance_tests');
  }

  if (component.type === 'decision_engine' || component.type === 'execution') {
    requirements.push('scenario_tests', 'edge_case_tests');
  }

  if (testingLevel === 'advanced') {
    requirements.push('load_tests', 'security_tests');
  }

  return requirements;
}

return [{
  json: {
    ...context,
    architecture_blueprint: architectureBlueprint,
    implementation_strategy: 'phased_deployment_with_rollback'
  }
}];

// Generate comprehensive solution architecture prompt
