return [{
  json: {
    ...context,
    deepseek_prompt: architecturePrompt,
    analysis_type: 'solution_architecture_generation'
  }
}];

// Process and validate solution architecture generation
const aiResponse = $input.first().json;
const originalContext = items.find(item => item.json.deepseek_prompt)?.json;

if (!aiResponse.choices || !aiResponse.choices[0]?.message?.content) {
  return [{
    json: {
      error: 'Invalid AI response from solution architecture generation',
      status: 'ai_error'
    }
  }];
}

try {
  const solutionResult = JSON.parse(aiResponse.choices[0].message.content);

  // Validate and enhance the solution
  const enhancedSolution = {
    solution_id: generateSolutionId(),
    request_id: originalContext.request_id,
    character_id: originalContext.character_context.character_id,
    session_id: originalContext.character_context.character_id + '_' + Date.now(),
    timestamp: new Date().toISOString(),
    automation_type: originalContext.architecture_blueprint.automation_type,
    solution_architecture: solutionResult,
    implementation_plan: createImplementationPlan(solutionResult, originalContext),
    quality_assurance: performQualityAssurance(solutionResult),
    deployment_package: createDeploymentPackage(solutionResult, originalContext),
    character_experience: designCharacterExperience(solutionResult, originalContext),
    success_metrics: defineSuccessMetrics(solutionResult, originalContext),
    next_actions: generateNextActions(solutionResult, originalContext),
    metadata: {
      ai_provider: 'deepseek',
      model: 'deepseek-chat',
      tokens_used: aiResponse.usage?.total_tokens || 0,
      generation_time: Date.now() - new Date(originalContext.timestamp).getTime(),
      architecture_complexity: originalContext.architecture_blueprint.components.length,
      documentation_level: originalContext.delivery_preferences.documentation_level
    }
  };

  function generateSolutionId() {
    return 'sol_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }

  function createImplementationPlan(solution, context) {
    const phases = solution.implementation_roadmap?.development_phases || [];
    return {
      total_phases: phases.length,
      estimated_total_time: phases.reduce((sum, phase) => {
        const duration = parseInt(phase.estimated_duration) || 0;
        return sum + duration;
      }, 0),
      critical_path: identifyCriticalPath(phases),
      resource_requirements: calculateResourceRequirements(solution, context),
      risk_assessment: assessImplementationRisks(phases),
      quality_gates: defineQualityGates(phases)
    };
  }

  function performQualityAssurance(solution) {
    return {
      code_quality_checks: [
        'syntax_validation',
        'dependency_analysis',
        'security_review',
        'performance_analysis'
      ],
      architecture_validation: [
        'component_integrity',
        'integration_completeness',
        'scalability_assessment',
        'error_handling_coverage'
      ],
      documentation_review: [
        'completeness_check',
        'clarity_assessment',
        'accuracy_verification',
        'usability_evaluation'
      ],
      test_coverage: calculateTestCoverage(solution),
      overall_quality_score: calculateOverallQualityScore(solution)
    };
  }

  function createDeploymentPackage(solution, context) {
    return {
      package_contents: [
        'source_code',
        'configuration_files',
        'documentation',
        'testing_suite',
        'deployment_scripts',
        'monitoring_setup'
      ],
      deployment_strategy: solution.deployment_plan?.deployment_strategy || 'phased',
      environment_requirements: {
        'n8n_version': '>=1.0.0',
        'python_version': '>=3.8',
        'memory_requirement': '>=512MB',
        'storage_requirement': '>=100MB'
      },
      installation_complexity: assessInstallationComplexity(solution),
      rollback_procedures: solution.deployment_plan?.rollback_procedures || [],
      monitoring_setup: solution.deployment_plan?.monitoring_setup || []
    };
  }

  function designCharacterExperience(solution, context) {
    const interface = solution.code_generation?.character_interface || {};
    return {
      interaction_methods: interface.interaction_methods || ['voice_commands', 'menu_interface'],
      learning_curve: 'gentle_with_guidance',
      customization_options: interface.customization_options || [],
      feedback_systems: interface.feedback_systems || ['visual_notifications', 'status_messages'],
      help_system: {
        'in_context_help': true,
        'tutorial_mode': true,
        'troubleshooting_guide': true,
        'community_support': true
      },
      accessibility_features: [
        'simple_language',
        'visual_indicators',
        'audio_feedback',
        'keyboard_navigation'
      ]
    };
  }

  function defineSuccessMetrics(solution, context) {
    const metrics = solution.success_metrics || {};
    return {
      performance_metrics: metrics.performance_metrics || [
        'response_time < 2 seconds',
        'automation_accuracy > 90%',
        'resource_efficiency > 80%'
      ],
      reliability_metrics: metrics.reliability_metrics || [
        'uptime > 99%',
        'error_rate < 1%',
        'recovery_time < 30 seconds'
      ],
      user_satisfaction_metrics: metrics.user_satisfaction_metrics || [
        'ease_of_use_score > 4/5',
        'effectiveness_rating > 4/5',
        'recommendation_score > 80%'
      ],
      business_value_metrics: metrics.business_value_metrics || [
        'time_saved_per_session',
        'success_rate_improvement',
        'character_satisfaction_increase'
      ]
    };
  }

  function generateNextActions(solution, context) {
    const actions = [
      'Review and approve solution architecture',
      'Set up development environment',
      'Begin Phase 1 implementation according to roadmap'
    ];

    if (context.delivery_preferences.include_setup_instructions) {
      actions.push('Prepare setup and configuration documentation');
    }

    if (context.delivery_preferences.include_usage_examples) {
      actions.push('Create usage examples and tutorials');
    }

    actions.push('Schedule implementation review session');

    return actions;
  }

  // Helper functions
  function identifyCriticalPath(phases) {
    return phases.map(phase => phase.phase_name).filter(name => 
      name.includes('core') || name.includes('essential') || name.includes('foundation')
    );
  }

  function calculateResourceRequirements(solution, context) {
    const components = solution.architecture_design?.component_details?.length || 0;
    return {
      development_time: components * 3, // 3 days per component average
      testing_time: components * 1.5, // 1.5 days testing per component
      review_time: components * 0.5, // 0.5 days review per component
      total_estimated_time: components * 5
    };
  }

  function assessImplementationRisks(phases) {
    return [
      'Integration complexity between components',
      'API availability and compatibility',
      'Performance under load conditions',
      'Character adoption and learning curve'
    ];
  }

  function defineQualityGates(phases) {
    return phases.map((phase, index) => ({
      gate_name: `Phase ${index + 1} Completion Gate`,
      criteria: [
        'All components implemented according to specifications',
        'Integration tests passing',
        'Documentation complete',
        'Performance requirements met'
      ]
    }));
  }

  function calculateTestCoverage(solution) {
    const components = solution.architecture_design?.component_details?.length || 0;
    return Math.min(85 + (components * 2), 95); // 85% base + 2% per component
  }

  function calculateOverallQualityScore(solution) {
    let score = 70; // Base score

    if (solution.architecture_design?.component_details?.length > 0) score += 10;
    if (solution.code_generation?.complete_codebase) score += 10;
    if (solution.documentation_package?.character_friendly_guide) score += 5;
    if (solution.testing_strategy?.test_scenarios?.length > 0) score += 5;

    return Math.min(score, 100);
  }

  function assessInstallationComplexity(solution) {
    const components = solution.architecture_design?.component_details?.length || 0;
    if (components <= 2) return 'simple';
    if (components <= 4) return 'moderate';
    return 'complex';
  }

  return [{
    json: enhancedSolution
  }];

} catch (error) {
  return [{
    json: {
      error: 'Failed to process solution architecture generation',
      details: error.message,
      raw_response: aiResponse.choices[0].message.content,
      status: 'processing_error'
    }
  }];
}

// Create deployment artifacts and documentation
const solution = $input.first().json;

// Create comprehensive deployment package
const deploymentArtifacts = {
  solution_package: {
    package_id: solution.solution_id,
    package_name: `${solution.automation_type}_automation_package`,
    version: '1.0.0',
    created_at: solution.timestamp,
    character_id: solution.character_id,
    package_contents: {
      source_code: extractSourceCode(solution.solution_architecture),
      configuration_files: extractConfigurationFiles(solution.solution_architecture),
      documentation: extractDocumentation(solution.solution_architecture),
      testing_suite: extractTestingSuite(solution.solution_architecture),
      deployment_scripts: generateDeploymentScripts(solution),
      setup_instructions: solution.solution_architecture.documentation_package?.setup_instructions || {}
    }
  },
  character_interface: {
    interface_type: 'voice_and_menu',
    activation_commands: generateActivationCommands(solution),
    status_indicators: generateStatusIndicators(solution),
    customization_options: generateCustomizationOptions(solution),
    help_system: generateHelpSystem(solution)
  },
  monitoring_setup: {
    metrics_to_track: generateMetricsToTrack(solution),
    alert_conditions: generateAlertConditions(solution),
    dashboard_configuration: generateDashboardConfiguration(solution),
    logging_configuration: generateLoggingConfiguration(solution)
  }
};

function extractSourceCode(architecture) {
  const codebase = architecture.code_generation?.complete_codebase;
  if (!codebase) return { error: 'No code generated' };

  return {
    main_entry_point: codebase.main_entry_point || 'main.py',
    components: codebase.component_implementations || [],
    integration_code: codebase.integration_code || '',
    total_components: codebase.component_implementations?.length || 0,
    estimated_lines_of_code: estimateLinesOfCode(codebase)
  };
}

function extractConfigurationFiles(architecture) {
  return {
    config_files: architecture.code_generation?.complete_codebase?.configuration_files || [],
    environment_variables: generateEnvironmentVariables(architecture),
    default_settings: generateDefaultSettings(architecture)
  };
}

function extractDocumentation(architecture) {
  const docs = architecture.documentation_package;
  return {
    character_guide: docs?.character_friendly_guide || {},
    technical_docs: docs?.technical_documentation || {},
    setup_instructions: docs?.setup_instructions || {},
    total_documentation_files: countDocumentationFiles(docs)
  };
}

function extractTestingSuite(architecture) {
  const testing = architecture.testing_strategy;
  return {
    test_levels: testing?.testing_levels || {},
    test_scenarios: testing?.test_scenarios || [],
    automation_framework: testing?.automation_testing || 'pytest',
    estimated_test_coverage: testing?.test_coverage || 80
