// Helper functions
function estimateLinesOfCode(codebase) {
  let totalLines = 0;
  if (codebase.main_entry_point) totalLines += 100;
  if (codebase.component_implementations) {
    totalLines += codebase.component_implementations.length * 150;
  }
  if (codebase.integration_code) totalLines += 200;
  return totalLines;
}

function generateEnvironmentVariables(architecture) {
  return [
    'DEEPSEEK_API_KEY=your_api_key',
    'N8N_WEBHOOK_URL=your_webhook_url',
    'LOG_LEVEL=INFO',
    'AUTOMATION_MODE=standard'
  ];
}

function generateDefaultSettings(architecture) {
  return {
    automation_enabled: true,
    response_time_limit: 5000,
    max_concurrent_operations: 3,
    notification_enabled: true,
    logging_enabled: true
  };
}

function countDocumentationFiles(docs) {
  let count = 0;
  if (docs?.character_friendly_guide) count += 1;
  if (docs?.technical_documentation) count += 1;
  if (docs?.setup_instructions) count += 1;
  return count;
}

return [{
  json: {
    ...solution,
    deployment_artifacts: deploymentArtifacts,
    package_status: 'ready_for_deployment'
  }
}];

