function extractKeyFeatures(solution) {
  const features = [];
  const architecture = solution.solution_architecture.architecture_design;

  if (architecture?.component_details) {
    architecture.component_details.forEach(component => {
      if (component.technical_specifications?.functionality) {
        features.push(...component.technical_specifications.functionality);
      }
    });
  }

  // Return unique features (first 10)
  return [...new Set(features)].slice(0, 10);
}

